 public static FlowDocument BuildDocument(InvoiceDraft invoice)
 {
  var doc=new FlowDocument{PageWidth=793.7,PageHeight=1122.5,PagePadding=new Thickness(65,55,65,55),ColumnWidth=double.PositiveInfinity,FontFamily=new FontFamily("Segoe UI"),FontSize=12,Background=Brushes.White};
  var header=new Table{CellSpacing=0};header.Columns.Add(new TableColumn{Width=new GridLength(360)});header.Columns.Add(new TableColumn{Width=new GridLength(290)});var hg=new TableRowGroup();var hr=new TableRow();hr.Cells.Add(BrandCell(invoice.ShowLogoSnapshot,invoice.LogoPngBase64Snapshot,invoice.CompanySnapshot,invoice.HeaderLine1Snapshot,invoice.HeaderLine2Snapshot,invoice.HeaderLine3Snapshot,invoice.HeaderLine4Snapshot));hr.Cells.Add(Cell("RECHNUNG",invoice.DisplayNumber+"\nRechnungsdatum: "+invoice.InvoiceDate.ToString("dd.MM.yyyy")+"\nLeistungsdatum: "+invoice.ServiceDate.ToString("dd.MM.yyyy"),22,FontWeights.Bold,TextAlignment.Right));hg.Rows.Add(hr);header.RowGroups.Add(hg);doc.Blocks.Add(header);
  if(invoice.Status=="Storniert"){var cancelled=new Paragraph(new Run("STORNIERT")){Foreground=new SolidColorBrush(Color.FromRgb(170,25,25)),Background=new SolidColorBrush(Color.FromRgb(255,235,235)),FontSize=23,FontWeight=FontWeights.Bold,TextAlignment=TextAlignment.Center,Padding=new Thickness(10),Margin=new Thickness(0,24,0,18)};doc.Blocks.Add(cancelled);doc.Blocks.Add(new Paragraph(new Run($"Storniert am {invoice.CancelledAt:dd.MM.yyyy HH:mm}. Grund: {invoice.CancellationReason}")){Foreground=new SolidColorBrush(Color.FromRgb(150,30,30)),Margin=new Thickness(0,0,0,18)});}
  var addr=new Table{CellSpacing=0,Margin=new Thickness(0,28,0,25)};addr.Columns.Add(new TableColumn{Width=new GridLength(360)});addr.Columns.Add(new TableColumn{Width=new GridLength(290)});var ag=new TableRowGroup();var ar=new TableRow();ar.Cells.Add(Cell("Rechnung an",invoice.CustomerAddressSnapshot,12,FontWeights.SemiBold,TextAlignment.Left));ar.Cells.Add(Cell("Zahlungsinformationen",$"Kundennummer: {invoice.CustomerNumber}\nZahlungsziel: {invoice.PaymentTermDays} Tage\nFällig am: {invoice.InvoiceDate.AddDays(invoice.PaymentTermDays):dd.MM.yyyy}",12,FontWeights.SemiBold,TextAlignment.Left));ag.Rows.Add(ar);addr.RowGroups.Add(ag);doc.Blocks.Add(addr);
  if(!string.IsNullOrWhiteSpace(invoice.IntroText))doc.Blocks.Add(new Paragraph(new Run(invoice.IntroText)){Margin=new Thickness(0,0,0,18)});
  var table=new Table{CellSpacing=0,BorderBrush=new SolidColorBrush(Color.FromRgb(205,215,209)),BorderThickness=new Thickness(1)};double[] widths={34,235,55,64,86,62,72};foreach(var w in widths)table.Columns.Add(new TableColumn{Width=new GridLength(w)});var group=new TableRowGroup();var h=new TableRow{Background=new SolidColorBrush(Color.FromRgb(20,83,45)),Foreground=Brushes.White};var heads=invoice.IsSmallBusinessSnapshot?new[]{"Pos.","Bezeichnung","Menge","Einheit","Einzelpreis","","Netto"}:new[]{"Pos.","Bezeichnung","Menge","Einheit","Einzelpreis","USt.","Netto"};foreach(var x in heads)h.Cells.Add(GridCell(x,true,TextAlignment.Center));group.Rows.Add(h);var pos=1;foreach(var line in invoice.Lines){var r=new TableRow();r.Cells.Add(GridCell(pos++.ToString(),false,TextAlignment.Center));r.Cells.Add(GridCell(line.Description,false,TextAlignment.Left));r.Cells.Add(GridCell(line.Quantity.ToString("0.##",De),false,TextAlignment.Right));r.Cells.Add(GridCell(line.Unit,false,TextAlignment.Center));r.Cells.Add(GridCell(Money(line.UnitPrice),false,TextAlignment.Right));r.Cells.Add(GridCell(invoice.IsSmallBusinessSnapshot?"":line.VatRate.ToString("0.##",De)+" %",false,TextAlignment.Right));r.Cells.Add(GridCell(Money(line.NetAmount),false,TextAlignment.Right));group.Rows.Add(r);}table.RowGroups.Add(group);doc.Blocks.Add(table);
  var totals=new Table{CellSpacing=0,Margin=new Thickness(380,18,0,22)};totals.Columns.Add(new TableColumn{Width=new GridLength(140)});totals.Columns.Add(new TableColumn{Width=new GridLength(130)});var tg=new TableRowGroup();AddTotal(tg,"Nettosumme",invoice.NetTotal,false);if(!invoice.IsSmallBusinessSnapshot)AddTotal(tg,"Umsatzsteuer",invoice.VatTotal,false);AddTotal(tg,"Gesamtsumme",invoice.GrossTotal,true);totals.RowGroups.Add(tg);doc.Blocks.Add(totals);
