  foreach(var line in new[]{invoice.FooterLine1Snapshot,invoice.FooterLine2Snapshot,invoice.FooterLine3Snapshot,invoice.FooterLine4Snapshot}.Where(x=>!string.IsNullOrWhiteSpace(x)))doc.Blocks.Add(new Paragraph(new Run(line)){FontSize=9,Foreground=Brushes.DimGray,Margin=new Thickness(0,2,0,0)});  var footer=new Paragraph(new Run("Erstellt mit dem SaarOSS-Rechnungsprogramm")){FontSize=9,Foreground=Brushes.Gray,TextAlignment=TextAlignment.Center,BorderBrush=new SolidColorBrush(Color.FromRgb(220,225,222)),BorderThickness=new Thickness(0,1,0,0),Padding=new Thickness(0,12,0,0),Margin=new Thickness(0,30,0,0)};doc.Blocks.Add(footer);return doc;
 }
 private static TableCell BrandCell(bool showLogo,string logoBase64,string company,string line1,string line2,string line3,string line4){var stack=new StackPanel();if(showLogo&&!string.IsNullOrWhiteSpace(logoBase64)){try{var bytes=Convert.FromBase64String(logoBase64);var image=new BitmapImage();using var ms=new MemoryStream(bytes);image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.StreamSource=ms;image.EndInit();stack.Children.Add(new System.Windows.Controls.Image{Source=image,MaxWidth=210,MaxHeight=85,Stretch=Stretch.Uniform,HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,0,0,8)});}catch{}}stack.Children.Add(new TextBlock{Text=company,FontWeight=FontWeights.SemiBold,FontSize=11,TextWrapping=TextWrapping.Wrap});if(!string.IsNullOrWhiteSpace(line1))stack.Children.Add(new TextBlock{Text=line1,FontSize=10,Foreground=Brushes.DimGray,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,5,0,0)});if(!string.IsNullOrWhiteSpace(line2))stack.Children.Add(new TextBlock{Text=line2,FontSize=10,Foreground=Brushes.DimGray,TextWrapping=TextWrapping.Wrap});if(!string.IsNullOrWhiteSpace(line3))stack.Children.Add(new TextBlock{Text=line3,FontSize=10,Foreground=Brushes.DimGray,TextWrapping=TextWrapping.Wrap});if(!string.IsNullOrWhiteSpace(line4))stack.Children.Add(new TextBlock{Text=line4,FontSize=10,Foreground=Brushes.DimGray,TextWrapping=TextWrapping.Wrap});return new TableCell(new BlockUIContainer(stack)){Padding=new Thickness(8)};}
 private static Block? BuildPaymentSection(InvoiceDraft invoice){if(!invoice.ShowBankDetailsSnapshot)return null;var purpose=(invoice.PurposeTemplateSnapshot??"").Replace("{Rechnungsnummer}",invoice.DisplayNumber??"").Replace("{Kundennummer}",invoice.CustomerNumber??"");var lines=new List<string>();if(!string.IsNullOrWhiteSpace(invoice.PaymentInstructionSnapshot))lines.Add(invoice.PaymentInstructionSnapshot);if(!string.IsNullOrWhiteSpace(invoice.AccountHolderSnapshot))lines.Add("Kontoinhaber: "+invoice.AccountHolderSnapshot);if(!string.IsNullOrWhiteSpace(invoice.BankNameSnapshot))lines.Add("Bank: "+invoice.BankNameSnapshot);if(!string.IsNullOrWhiteSpace(invoice.IbanSnapshot))lines.Add("IBAN: "+FormatSnapshotIban(invoice.IbanSnapshot));if(!string.IsNullOrWhiteSpace(invoice.BicSnapshot))lines.Add("BIC: "+invoice.BicSnapshot);if(!string.IsNullOrWhiteSpace(purpose))lines.Add("Verwendungszweck: "+purpose);if(lines.Count==0)return null;var p=new Paragraph{Margin=new Thickness(0,18,0,12),Padding=new Thickness(12),Background=new SolidColorBrush(Color.FromRgb(246,249,247)),BorderBrush=new SolidColorBrush(Color.FromRgb(205,218,210)),BorderThickness=new Thickness(1)};p.Inlines.Add(new Run("Zahlungsinformationen\n"){FontWeight=FontWeights.Bold,FontSize=13});for(var i=0;i<lines.Count;i++)p.Inlines.Add(new Run(lines[i]+(i<lines.Count-1?"\n":"")){FontSize=10});return p;}
 private static string FormatSnapshotIban(string value){var s=new string((value??"").Where(char.IsLetterOrDigit).Select(char.ToUpperInvariant).ToArray());return string.Join(" ",Enumerable.Range(0,(s.Length+3)/4).Select(i=>s.Substring(i*4,Math.Min(4,s.Length-i*4))));} private static TableCell Cell(string title,string body,double size,FontWeight weight,TextAlignment align){var p=new Paragraph{Margin=new Thickness(0),TextAlignment=align};if(!string.IsNullOrWhiteSpace(title))p.Inlines.Add(new Run(title+"\n"){FontWeight=weight,FontSize=size});if(!string.IsNullOrWhiteSpace(body))p.Inlines.Add(new Run(body){FontSize=11});return new TableCell(p){Padding=new Thickness(8)};}
 private static TableCell GridCell(string text,bool bold,TextAlignment align)=>new(new Paragraph(new Run(text)){Margin=new Thickness(0),TextAlignment=align,FontWeight=bold?FontWeights.SemiBold:FontWeights.Normal}){Padding=new Thickness(7,6,7,6),BorderBrush=new SolidColorBrush(Color.FromRgb(215,222,218)),BorderThickness=new Thickness(0,0,0,1)};
 private static void AddTotal(TableRowGroup g,string label,decimal value,bool strong){var r=new TableRow();r.Cells.Add(GridCell(label,strong,TextAlignment.Left));r.Cells.Add(GridCell(Money(value),strong,TextAlignment.Right));g.Rows.Add(r);}private static string Money(decimal v)=>v.ToString("N2",De)+" €";
 public static void SavePdf(InvoiceDraft document,string path)
 {
  var pages=BuildPdfPages(document);
  var logo=CreatePdfLogo(document.ShowLogoSnapshot,document.LogoPngBase64Snapshot);
  var objects=new List<byte[]>();
  objects.Add(Ascii("<< /Type /Catalog /Pages 2 0 R >>"));
  var pageStart=3;var fontRegular=pageStart+pages.Count*2;var fontBold=fontRegular+1;var logoObject=logo is null?0:fontBold+1;
  var kids=string.Join(" ",Enumerable.Range(0,pages.Count).Select(i=>$"{pageStart+i*2} 0 R"));
  objects.Add(Ascii($"<< /Type /Pages /Kids [{kids}] /Count {pages.Count} >>"));
  for(var i=0;i<pages.Count;i++){
   var pageObj=pageStart+i*2;var contentObj=pageObj+1;
   var xobject=logo is null?"":$" /XObject << /Logo {logoObject} 0 R >>";
   objects.Add(Ascii($"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 {fontRegular} 0 R /F2 {fontBold} 0 R >>{xobject} >> /Contents {contentObj} 0 R >>"));
   var bytes=Ascii(pages[i]);objects.Add(Combine(Ascii($"<< /Length {bytes.Length} >>\nstream\n"),bytes,Ascii("\nendstream")));
  }
  objects.Add(Ascii("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>"));
  objects.Add(Ascii("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>"));
  if(logo is not null){objects.Add(Combine(Ascii($"<< /Type /XObject /Subtype /Image /Width {logo.Value.Width} /Height {logo.Value.Height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /FlateDecode /Length {logo.Value.Data.Length} >>\nstream\n"),logo.Value.Data,Ascii("\nendstream")));}
  WritePdf(path,objects);
 } private static (int Width,int Height,byte[] Data)? CreatePdfLogo(bool showLogo,string base64)
 {
  if(!showLogo||string.IsNullOrWhiteSpace(base64))return null;
  try{
   var bytes=Convert.FromBase64String(base64);using var input=new MemoryStream(bytes);
   var decoder=BitmapDecoder.Create(input,BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad);var source=decoder.Frames[0];
   const int maxWidth=500;const int maxHeight=250;var scale=Math.Min(1d,Math.Min((double)maxWidth/source.PixelWidth,(double)maxHeight/source.PixelHeight));
   var width=Math.Max(1,(int)Math.Round(source.PixelWidth*scale));var height=Math.Max(1,(int)Math.Round(source.PixelHeight*scale));
   BitmapSource sized=source;if(width!=source.PixelWidth||height!=source.PixelHeight)sized=new TransformedBitmap(source,new ScaleTransform(scale,scale));
   var rgb=new FormatConvertedBitmap(sized,PixelFormats.Rgb24,null,0);var stride=(rgb.PixelWidth*rgb.Format.BitsPerPixel+7)/8;var raw=new byte[stride*rgb.PixelHeight];rgb.CopyPixels(raw,stride,0);
   using var compressed=new MemoryStream();using(var z=new ZLibStream(compressed,CompressionLevel.Optimal,true)){z.Write(raw,0,raw.Length);}return(rgb.PixelWidth,rgb.PixelHeight,compressed.ToArray());
  }catch{return null;}
 }
 private static List<string> BuildPdfPages(InvoiceDraft inv){var pages=new List<string>();var lines=inv.Lines;const int perPage=22;for(int start=0;start<Math.Max(1,lines.Count);start+=perPage){var sb=new StringBuilder();sb.Append("1 1 1 rg 0 0 595 842 re f 0 0 0 rg\n");if(inv.ShowLogoSnapshot&&!string.IsNullOrWhiteSpace(inv.LogoPngBase64Snapshot))sb.Append("q 110 0 0 55 50 730 cm /Logo Do Q\n");Text(sb,50,790,18,true,"RECHNUNG");Text(sb,420,790,11,true,inv.DisplayNumber);var company=(inv.CompanySnapshot??"").Split(new[]{"\r\n","\n"},StringSplitOptions.None);var y=inv.ShowLogoSnapshot&&!string.IsNullOrWhiteSpace(inv.LogoPngBase64Snapshot)?710d:760d;foreach(var l in company.Take(7)){Text(sb,50,y,9,false,l);y-=12;}foreach(var l in new[]{inv.HeaderLine1Snapshot,inv.HeaderLine2Snapshot,inv.HeaderLine3Snapshot,inv.HeaderLine4Snapshot}.Where(x=>!string.IsNullOrWhiteSpace(x))){Text(sb,50,y,8,false,l,72);y-=11;}Text(sb,360,760,9,true,"Rechnungsdatum:");Text(sb,470,760,9,false,inv.InvoiceDate.ToString("dd.MM.yyyy"));Text(sb,360,745,9,true,"Leistungsdatum:");Text(sb,470,745,9,false,inv.ServiceDate.ToString("dd.MM.yyyy"));Text(sb,360,730,9,true,"Fällig am:");Text(sb,470,730,9,false,inv.InvoiceDate.AddDays(inv.PaymentTermDays).ToString("dd.MM.yyyy"));if(inv.Status=="Storniert"){sb.Append("1 0.9 0.9 rg 45 625 505 35 re f 0.65 0.05 0.05 rg\n");Text(sb,240,637,18,true,"STORNIERT");sb.Append("0 0 0 rg\n");}Text(sb,50,600,9,true,"Rechnung an");y=582;foreach(var l in (inv.CustomerAddressSnapshot??"").Split(new[]{"\r\n","\n"},StringSplitOptions.None).Take(6)){Text(sb,50,y,10,false,l);y-=13;}Text(sb,365,600,9,true,"Kundennummer:");Text(sb,470,600,9,false,inv.CustomerNumber);y=510;y=WrappedText(sb,50,y,10,false,inv.IntroText,88,14)-14;sb.Append("0.08 0.33 0.18 rg 45 ").Append(y-5).Append(" 505 22 re f 1 1 1 rg\n");var headers=new[]{("Pos",50), ("Bezeichnung",82),("Menge",330),("Einheit",378),("Preis",430),("Netto",495)};foreach(var h in headers)Text(sb,h.Item2,y+2,8,true,h.Item1);sb.Append("0 0 0 rg\n");y-=22;var subset=lines.Skip(start).Take(perPage).ToList();var p=start+1;foreach(var l in subset){Text(sb,50,y,8,false,p++.ToString());Text(sb,82,y,8,false,l.Description,34);Text(sb,335,y,8,false,l.Quantity.ToString("0.##",De));Text(sb,378,y,8,false,l.Unit,9);Text(sb,430,y,8,false,Money(l.UnitPrice));Text(sb,495,y,8,false,Money(l.NetAmount));sb.Append("0.85 0.88 0.86 RG 45 ").Append(y-4).Append(" m 550 ").Append(y-4).Append(" l S\n");y-=19;}if(start+perPage>=lines.Count){y-=10;Text(sb,375,y,9,false,"Nettosumme");Text(sb,495,y,9,true,Money(inv.NetTotal));y-=17;if(!inv.IsSmallBusinessSnapshot){Text(sb,375,y,9,false,"Umsatzsteuer");Text(sb,495,y,9,true,Money(inv.VatTotal));y-=21;}Text(sb,375,y,12,true,"Gesamtsumme");Text(sb,485,y,12,true,Money(inv.GrossTotal));y-=37;if(inv.IsSmallBusinessSnapshot){y=WrappedText(sb,50,y,9,true,inv.SmallBusinessNoticeSnapshot.Replace("§","Paragraph"),95,13)-10;}if(inv.ShowBankDetailsSnapshot){WritePaymentPdf(sb,inv,ref y);}else{y=WrappedText(sb,50,y,9,false,inv.ClosingText,95,13);}if(inv.Status=="Storniert"){y-=30;Text(sb,50,y,9,true,$"Storniert am {inv.CancelledAt:dd.MM.yyyy HH:mm}. Grund: {inv.CancellationReason}",90);}}Text(sb,200,28,8,false,$"Seite {pages.Count+1} - Erstellt mit dem SaarOSS-Rechnungsprogramm");pages.Add(sb.ToString());}return pages;}
 private static void WritePaymentPdf(StringBuilder sb,InvoiceDraft inv,ref double y){y-=6;Text(sb,50,y,11,true,"Zahlungsinformationen");y-=15;if(!string.IsNullOrWhiteSpace(inv.PaymentInstructionSnapshot))y=WrappedText(sb,50,y,8,false,inv.PaymentInstructionSnapshot,95,11)-2;if(!string.IsNullOrWhiteSpace(inv.AccountHolderSnapshot)){Text(sb,50,y,8,false,"Kontoinhaber: "+inv.AccountHolderSnapshot,90);y-=11;}if(!string.IsNullOrWhiteSpace(inv.BankNameSnapshot)){Text(sb,50,y,8,false,"Bank: "+inv.BankNameSnapshot,90);y-=11;}if(!string.IsNullOrWhiteSpace(inv.IbanSnapshot)){Text(sb,50,y,8,false,"IBAN: "+FormatPdfIban(inv.IbanSnapshot),90);y-=11;}if(!string.IsNullOrWhiteSpace(inv.BicSnapshot)){Text(sb,50,y,8,false,"BIC: "+inv.BicSnapshot,90);y-=11;}var purpose=(inv.PurposeTemplateSnapshot??"").Replace("{Rechnungsnummer}",inv.DisplayNumber??"").Replace("{Kundennummer}",inv.CustomerNumber??"");if(!string.IsNullOrWhiteSpace(purpose)){y=WrappedText(sb,50,y,8,false,"Verwendungszweck: "+purpose,95,11)-3;}foreach(var line in new[]{inv.FooterLine1Snapshot,inv.FooterLine2Snapshot,inv.FooterLine3Snapshot,inv.FooterLine4Snapshot}.Where(x=>!string.IsNullOrWhiteSpace(x))){Text(sb,50,y,8,false,line,95);y-=11;}}
 private static string FormatPdfIban(string value){var s=new string((value??"").Where(char.IsLetterOrDigit).Select(char.ToUpperInvariant).ToArray());return string.Join(" ",Enumerable.Range(0,(s.Length+3)/4).Select(i=>s.Substring(i*4,Math.Min(4,s.Length-i*4))));} private static double WrappedText(StringBuilder sb,double x,double y,double size,bool bold,string text,int maxChars,double lineHeight)
 {
  if(string.IsNullOrWhiteSpace(text))return y;
  var words=text.Replace("\r"," ").Replace("\n"," ").Split(' ',StringSplitOptions.RemoveEmptyEntries);var line=new StringBuilder();
  foreach(var word in words){if(line.Length>0&&line.Length+1+word.Length>maxChars){Text(sb,x,y,size,bold,line.ToString(),maxChars+5);y-=lineHeight;line.Clear();}if(line.Length>0)line.Append(' ');line.Append(word);}if(line.Length>0){Text(sb,x,y,size,bold,line.ToString(),maxChars+5);y-=lineHeight;}return y;
 }
 private static void Text(StringBuilder sb,double x,double y,double size,bool bold,string text,int max=60){if(string.IsNullOrEmpty(text))return;var val=text.Length>max?text[..Math.Max(1,max-1)]+"...":text;sb.Append("BT /").Append(bold?"F2":"F1").Append(' ').Append(size.ToString(CultureInfo.InvariantCulture)).Append(" Tf ").Append(x.ToString(CultureInfo.InvariantCulture)).Append(' ').Append(y.ToString(CultureInfo.InvariantCulture)).Append(" Td ").Append(PdfString(val)).Append(" Tj ET\n");}
 private static string PdfString(string value){var b=new StringBuilder("(");foreach(var ch in value){if(ch=='('||ch==')'||ch=='\\')b.Append('\\').Append(ch);else if(ch>=32&&ch<=126)b.Append(ch);else b.Append('\\').Append(Convert.ToString(ToWinAnsi(ch),8).PadLeft(3,'0'));}return b.Append(')').ToString();}
 private static byte ToWinAnsi(char c)=>c switch{'ä'=>228,'ö'=>246,'ü'=>252,'Ä'=>196,'Ö'=>214,'Ü'=>220,'ß'=>223,'€'=>128,'–'=>150,'—'=>151,'„'=>132,'“'=>147,'’'=>146,'·'=>183,_=>(byte)'?'};
 private static byte[] Ascii(string s)=>Encoding.ASCII.GetBytes(s);private static byte[] Combine(params byte[][] parts){using var m=new MemoryStream();foreach(var p in parts)m.Write(p);return m.ToArray();}
 private static void WritePdf(string path,List<byte[]> objects){using var fs=new FileStream(path,FileMode.Create,FileAccess.Write);fs.Write(Ascii("%PDF-1.4\n%SaarOSS\n"));var offsets=new List<long>{0};for(var i=0;i<objects.Count;i++){offsets.Add(fs.Position);fs.Write(Ascii($"{i+1} 0 obj\n"));fs.Write(objects[i]);fs.Write(Ascii("\nendobj\n"));}var xref=fs.Position;fs.Write(Ascii($"xref\n0 {objects.Count+1}\n0000000000 65535 f \n"));for(var i=1;i<offsets.Count;i++)fs.Write(Ascii(offsets[i].ToString("0000000000")+" 00000 n \n"));fs.Write(Ascii($"trailer\n<< /Size {objects.Count+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF"));}
}
